  /// takes the run down (the task-ledger convention); the fa.log entry
  /// above already carries the facts.
  void _recordRateLimitRetry(
    int attempt,
    int maxAttempts,
    Duration delay,
    String reason,
  ) {
    final session = _session;
    if (session == null) return;
    unawaited(
      session
          .appendCustomEntry(
            customType: rateLimitRetryRecordType,
            data: {
              // The notice's attempt is the 1-based number of the attempt
              // the retry is about to run ("attempt 2/4" — recorded
              // as-is, so the record and the log face tell one story).
              'attempt': attempt,
              'max_attempts': maxAttempts,
