        // Full jitter adds up to 25%, never undercuts the base.
        expect(
          rateLimitBackoffFor(1, 1.0).inMilliseconds,
          greaterThanOrEqualTo(rateLimitBackoffBase.inMilliseconds),
        );
        expect(rateLimitBackoffFor(1, 1.0).inMilliseconds, 2500);
