      // Truncation is display-only ([_shortNoticeLine]).
      final rateLimited = matchesRateLimitWording(reason);
      final line = _shortNoticeLine(reason);
      io.writeln(
        _style.dim(
          '${rateLimited ? '[net] rate limited' : '[net] connection lost'} '
