              // was scheduled and then abandoned" (gh-1602 review r1
              // thread 6).
              'delay_ms': delay.inMilliseconds,
              'reason': reason,
              'ts': DateTime.now().toIso8601String(),
            },
          )
          .then((_) {})
          .catchError((Object error) {
            _logDiagnostic('429_retry persist failed sid=$_logSid: $error');
          }),
    );
